import pandas as pd, numpy as np, patsy, statsmodels.api as sm
from sklearn.model_selection import KFold
df = pd.read_csv('data.csv'); df['late_flag']=(df.D>12).astype(float)
richc = 'C(region) + C(tier) + bs(log_hist_days, df=6) + bs(log_pre_gmv, df=5) + orders + cat_share + bs(tenure, df=6)'
def cv(formula, data=df):
    kf=KFold(5,shuffle=True,random_state=1); pr=np.zeros(len(data)); yy=data.dY.values
    for tr,te in kf.split(data):
        ytr, Xtr = patsy.dmatrices(formula, data.iloc[tr], return_type='matrix')
        mm=sm.OLS(ytr,Xtr).fit(); pr[te]=patsy.build_design_matrices([Xtr.design_info], data.iloc[te])[0].A@mm.params
    return 1-((yy-pr)**2).sum()/((yy-yy.mean())**2).sum()
for k,s in [('线性','D'),('对数D','np.log(D)'),('cr(D,4)','cr(D, df=4)'),('cr(D,5)','cr(D, df=5)'),('cr(D,7)','cr(D, df=7)'),('断点10','D + I(np.maximum(D-10,0))'),('断点13','D + I(np.maximum(D-13,0))'),('D+late_flag','D + late_flag'),('D+late+断点10','D + late_flag + I(np.maximum(D-10,0))')]:
    print(f'{k:16s} CV-R2={cv(f"dY ~ {s} + {richc}"):.4f}')
